"""KDV hesapları."""
import warnings


def kdv_hesapla(tutar, oran=0.20):
    """Tutarın KDV'sini döndürür (kuruşa yuvarlanmış)."""
    return round(tutar * oran, 2)


def hesapKdvDahil(tutar, oran=0.20):
    """KDV dahil tutarı döndürür."""
    return round(tutar + kdv_hesapla(tutar, oran), 2)


def toplam_tutar(kalemler):
    """[(fiyat, adet, kdv_orani), ...] listesinin KDV dahil toplamı."""
    return round(sum(f * a + kdv_hesapla(f * a, o) for f, a, o in kalemler), 2)


# Geriye uyumluluk
def hesapKdv(tutar, oran=0.20):
    """Tutarın KDV'sini döndürür (kuruşa yuvarlanmış). [Deprecated: kdv_hesapla kullanın.]"""
    warnings.warn(
        "hesapKdv is deprecated, use kdv_hesapla instead",
        DeprecationWarning,
        stacklevel=2,
    )
    return kdv_hesapla(tutar, oran)

import unittest
import warnings

from fatura import hesapKdv, hesapKdvDahil, kdv_hesapla, toplam_tutar


class HesapTest(unittest.TestCase):
    def test_kdv(self):
        self.assertEqual(kdv_hesapla(100), 20.0)
        self.assertEqual(kdv_hesapla(100, 0.10), 10.0)

    def test_kdv_deprecated(self):
        """Eski hesapKdv hâlâ çalışmalı ama DeprecationWarning vermeli."""
        with self.assertWarns(DeprecationWarning):
            result = hesapKdv(100)
        self.assertEqual(result, 20.0)

    def test_kdv_deprecated_value(self):
        """hesapKdv, kdv_hesapla ile aynı sonucu vermelidir."""
        with warnings.catch_warnings():
            warnings.simplefilter("ignore", DeprecationWarning)
            self.assertEqual(hesapKdv(100), kdv_hesapla(100))

    def test_dahil(self):
        self.assertEqual(hesapKdvDahil(100), 120.0)

    def test_toplam(self):
        self.assertEqual(toplam_tutar([(100, 2, 0.2), (50, 1, 0.1)]), 295.0)


if __name__ == "__main__":
    unittest.main()

